"""Recreate the per-poem cutout masters from the NDL HQ scans.

    国立国会図書館_2541162_HQ  小倉百人一首 (1680)        ->  国立国会図書館_2541162_cutout
    国立国会図書館_2533667_HQ  錦百人一首あつま織 (1775)  ->  国立国会図書館_2533667_cutout

Run from this folder with Python 3.12:
    pip install -r requirements.txt
    python make_cutouts.py                                   # both books, into the folders here
    python make_cutouts.py --book ogura --only poem_080,poem_074
    python make_cutouts.py --out SOME_DIR --jobs 4           # writes SOME_DIR/<cutout folder>/
"""
import argparse, csv, os
from multiprocessing import Pool
import numpy as np
from PIL import Image
from scipy import ndimage as ndi

Image.MAX_IMAGE_PIXELS = None
HERE = os.path.dirname(os.path.abspath(__file__))
CROP_MAX_DEG = 0.03          # 0.03 deg over a 3700 px edge is under 2 px of drift
RECT_TOL_PX = 3.0            # frame line within this of a straight rotated rectangle -> no warp
BORDER = 32                  # extra source pixels around the mapped area (spline prefilter)
SPLINE_ORDER = 5

BOOKS = {
    'ogura': dict(src='国立国会図書館_2541162_HQ', out='国立国会図書館_2541162_cutout', margin=10),
    'nishiki': dict(src='国立国会図書館_2533667_HQ', out='国立国会図書館_2533667_cutout', margin=48),
}
CUT_COLS = ['name', 'scan', 'page', 'content', 'method', 'angle_deg', 'nonrigid_px', 'width', 'height',
            'scale_min', 'scale_max']
# index.csv: as cut.tsv, plus the master's file size; avif_q and avif_bytes stay empty here.
INDEX_COLS = ['file'] + CUT_COLS[1:] + ['master_bytes', 'avif_q', 'avif_bytes']


def pages(book):
    """(scan number, 'L'/'R') -> (output name, content)."""
    if book == 'ogura':
        return {(4 + (n - 1) // 2, 'R' if n % 2 else 'L'): (f'poem_{n:03d}', 'portrait and poem')
                for n in range(1, 101)}
    out = {(10, 'L'): ('poem_001', 'poem text only'), (11, 'L'): ('poem_001_portrait', 'portrait only'),
           (11, 'R'): ('poem_002', 'poem text only'), (12, 'R'): ('poem_002_portrait', 'portrait only'),
           (12, 'L'): ('poem_003', 'portrait and poem')}
    for n in range(4, 101):
        out[(13 + (n - 4) // 2, 'R' if n % 2 == 0 else 'L')] = (f'poem_{n:03d}', 'portrait and poem')
    return out


# ---------------------------------------------------------------- geometry

def edge_samples(g, n=400):
    """Points along the four frame curves, corner to corner."""
    C, P = g['C'], g['P']
    out = {}
    for e, (a, b, vert) in {'L': ('TL', 'BL', 1), 'R': ('TR', 'BR', 1), 'T': ('TL', 'TR', 0), 'B': ('BL', 'BR', 0)}.items():
        if vert:
            y = np.linspace(C[a][1], C[b][1], n); x = np.polyval(P[e], y)
        else:
            x = np.linspace(C[a][0], C[b][0], n); y = np.polyval(P[e], x)
        out[e] = (x, y)
    return out


def rigid_fit(g):
    """Best rotation of the frame: angle (rad, positive = page turned clockwise on the scan), side
    positions in the rotated frame, and the largest distance of the frame line from that rectangle."""
    s = edge_samples(g)

    def cost(th):
        c, sn = np.cos(th), np.sin(th)
        sides, dev, ss = {}, 0.0, 0.0
        for e, (x, y) in s.items():
            p = c * x + sn * y if e in 'LR' else -sn * x + c * y
            sides[e] = p.mean(); d = p - p.mean()
            ss += (d ** 2).sum(); dev = max(dev, np.abs(d).max())
        return ss, sides, dev

    grid = np.deg2rad(np.arange(-2, 2.0001, 0.01))
    th = grid[np.argmin([cost(t)[0] for t in grid])]
    lo, hi = th - np.deg2rad(0.01), th + np.deg2rad(0.01)
    for _ in range(60):                                  # golden-section refine
        m1, m2 = lo + .382 * (hi - lo), lo + .618 * (hi - lo)
        if cost(m1)[0] < cost(m2)[0]:
            hi = m2
        else:
            lo = m1
    th = (lo + hi) / 2
    _, sides, dev = cost(th)
    return th, sides, dev


def coons(P, C, u, v):
    """Unit-square coords (u right, v down; may go past 0..1 into the margin) -> source x, y."""
    tx = C['TL'][0] + (C['TR'][0] - C['TL'][0]) * u; ty = np.polyval(P['T'], tx)
    bx = C['BL'][0] + (C['BR'][0] - C['BL'][0]) * u; by = np.polyval(P['B'], bx)
    ly = C['TL'][1] + (C['BL'][1] - C['TL'][1]) * v; lx = np.polyval(P['L'], ly)
    ry = C['TR'][1] + (C['BR'][1] - C['TR'][1]) * v; rx = np.polyval(P['R'], ry)
    bil = lambda k: ((1 - u) * (1 - v) * C['TL'][k] + u * (1 - v) * C['TR'][k]
                     + (1 - u) * v * C['BL'][k] + u * v * C['BR'][k])
    return ((1 - v) * tx + v * bx + (1 - u) * lx + u * rx - bil(0),
            (1 - v) * ty + v * by + (1 - u) * ly + u * ry - bil(1))


def plan(g, margin):
    """Choose the method and build the output -> source coordinate map."""
    th, sides, dev = rigid_fit(g)
    if dev <= RECT_TOL_PX:
        if abs(np.degrees(th)) < CROP_MAX_DEG:
            s = edge_samples(g)                          # frame's mean position on the scan itself
            up = {e: (s[e][0] if e in 'LR' else s[e][1]).mean() for e in 'LRTB'}
            Wo = int(round(up['R'] - up['L'])) + 1 + 2 * margin
            Ho = int(round(up['B'] - up['T'])) + 1 + 2 * margin
            return dict(method='crop', angle=th, dev=dev, x0=int(round(up['L'])) - margin,
                        y0=int(round(up['T'])) - margin, W=Wo, H=Ho)
        Wo = int(round(sides['R'] - sides['L'])) + 1 + 2 * margin
        Ho = int(round(sides['B'] - sides['T'])) + 1 + 2 * margin
        X, Y = np.meshgrid(np.arange(Wo, dtype=np.float64), np.arange(Ho, dtype=np.float64))
        xr, yr = sides['L'] - margin + X, sides['T'] - margin + Y      # unit scale
        c, s = np.cos(th), np.sin(th)
        return dict(method='rotate', angle=th, dev=dev, sx=c * xr - s * yr, sy=s * xr + c * yr, W=Wo, H=Ho)
    Ws, Hs = int(round(g['w'])), int(round(g['h']))                     # the page's own size
    Wo, Ho = Ws + 1 + 2 * margin, Hs + 1 + 2 * margin
    X, Y = np.meshgrid(np.arange(Wo, dtype=np.float64), np.arange(Ho, dtype=np.float64))
    sx, sy = coons(g['P'], g['C'], (X - margin) / Ws, (Y - margin) / Hs)
    return dict(method='warp', angle=th, dev=dev, sx=sx, sy=sy, W=Wo, H=Ho)


def local_scale(sx, sy):
    """Smallest and largest source pixels per output pixel (1 = native scale)."""
    jx = np.hypot(np.diff(sx, axis=1), np.diff(sy, axis=1))
    jy = np.hypot(np.diff(sx, axis=0), np.diff(sy, axis=0))
    return float(min(jx.min(), jy.min())), float(max(jx.max(), jy.max()))


# ---------------------------------------------------------------- cutting

def cut_page(args):
    src_path, out_path, g, margin = args
    p = plan(g, margin)
    rgb = np.asarray(Image.open(src_path).convert('RGB'))
    if p['method'] == 'crop':
        out = rgb[p['y0']:p['y0'] + p['H'], p['x0']:p['x0'] + p['W']]
        smin = smax = 1.0
    else:
        sx, sy = p['sx'], p['sy']
        smin, smax = local_scale(sx, sy)
        x0 = max(int(np.floor(sx.min())) - BORDER, 0); y0 = max(int(np.floor(sy.min())) - BORDER, 0)
        x1 = min(int(np.ceil(sx.max())) + BORDER + 1, rgb.shape[1]); y1 = min(int(np.ceil(sy.max())) + BORDER + 1, rgb.shape[0])
        crop = rgb[y0:y1, x0:x1].astype(np.float64)
        coords = np.array([sy - y0, sx - x0])
        res = np.empty(sx.shape + (3,), np.float64)
        for ch in range(3):
            res[..., ch] = ndi.map_coordinates(crop[..., ch], coords, order=SPLINE_ORDER, mode='mirror', prefilter=True)
        out = np.clip(np.rint(res), 0, 255).astype(np.uint8)
    Image.fromarray(np.ascontiguousarray(out)).save(out_path, compress_level=9)
    print('wrote', out_path, flush=True)
    return dict(method=p['method'], angle_deg=round(float(np.degrees(p['angle'])), 3),
                nonrigid_px=round(float(p['dev']), 1), width=int(out.shape[1]), height=int(out.shape[0]),
                scale_min=round(smin, 4), scale_max=round(smax, 4))


def write_tables(out_dir, new_rows):
    """cut.tsv and index.csv for every page in the folder (rows from earlier runs are kept)."""
    rows = {}
    tsv = os.path.join(out_dir, 'cut.tsv')
    if os.path.exists(tsv):
        with open(tsv) as f:
            rows = {r['name']: r for r in csv.DictReader(f, delimiter='\t')}
    for r in new_rows:
        rows[r['name']] = {c: str(r[c]) for c in CUT_COLS}
    with open(tsv, 'w') as f:
        f.write('\t'.join(CUT_COLS) + '\n')
        for name in sorted(rows):
            f.write('\t'.join(rows[name][c] for c in CUT_COLS) + '\n')
    with open(os.path.join(out_dir, 'index.csv'), 'w', newline='') as f:
        w = csv.writer(f)
        w.writerow(INDEX_COLS)
        for name in sorted(rows):
            r = rows[name]
            w.writerow([r[c] for c in CUT_COLS] + [os.path.getsize(os.path.join(out_dir, name + '.png')), '', ''])


def main():
    ap = argparse.ArgumentParser(description='Recreate the cutout masters from the HQ scans.')
    ap.add_argument('--book', choices=sorted(BOOKS), help='only this book')
    ap.add_argument('--only', help='only these pages, e.g. poem_080,poem_001_portrait')
    ap.add_argument('--out', help='parent folder for the cutout folders (default: next to the scans)')
    ap.add_argument('--jobs', type=int, default=2, help='pages cut in parallel (about 1 GB each)')
    a = ap.parse_args()
    only = set(a.only.split(',')) if a.only else None
    for book in [a.book] if a.book else sorted(BOOKS):
        cfg = BOOKS[book]
        out_dir = os.path.join(a.out or HERE, cfg['out'])
        os.makedirs(out_dir, exist_ok=True)
        tasks, rows = [], []
        for (scan, side), (name, content) in sorted(pages(book).items(), key=lambda kv: kv[1][0]):
            if only and name not in only:
                continue
            key = f'{scan:04d}{side}'
            tasks.append((os.path.join(HERE, cfg['src'], f'{scan:04d}_0000.jpg'),
                          os.path.join(out_dir, name + '.png'), geometry(book, key), cfg['margin']))
            rows.append(dict(name=name, scan=f'{scan:04d}_0000.jpg', page='left' if side == 'L' else 'right',
                             content=content))
        if not tasks:
            continue
        with Pool(a.jobs) as pool:
            for r, res in zip(rows, pool.map(cut_page, tasks, chunksize=1)):
                r.update(res)
        write_tables(out_dir, rows)
        with open(os.path.join(out_dir, '.gitignore'), 'w') as f:
            f.write('*\n!.gitignore\n')


# ---------------------------------------------------------------- frame geometry

def geometry(book, key):
    """Frame of one page: quadratic curves of the outer frame line (P: x(y) for L/R, y(x) for T/B,
    highest power first), their corners (C), and the mean frame width and height (w, h)."""
    L, R, T, B, TL, TR, BL, BR, w, h = GEOMETRY[book][key]
    return dict(P={k: np.array(v) for k, v in zip('LRTB', (L, R, T, B))},
                C={k: np.array(v) for k, v in zip(('TL', 'TR', 'BL', 'BR'), (TL, TR, BL, BR))}, w=w, h=h)


